const row = $input.first()?.json;

if (!row || Object.keys(row).length === 0) {
  return [{ json: { found: false, message: 'No market data for this area/beds combination.' } }];
}

return [{
  json: {
    found: true,
    area: row.area,
    beds: row.beds,
    avg_sale_price: row.avg_sale_price,
    avg_rent_annual: row.avg_rent_annual,
    avg_price_sqft: row.avg_price_sqft,
    data_date: row.data_date,
    formatted: `In ${row.area}, ${row.beds}BR units currently average AED ${Number(row.avg_sale_price).toLocaleString()} for sale and AED ${Number(row.avg_rent_annual).toLocaleString()}/year for rent (data: ${row.data_date}).`
  }
}];
